mapper.select:
SELECT COUNT(1)
FROM t_baize_flow_job_definition d

LEFT JOIN t_baize_flow_job_instance i
ON i.id = (
SELECT t1.id
FROM t_baize_flow_job_instance t1
INNER JOIN (
SELECT job_definition_id, MAX(start_time) AS max_start_time
FROM t_baize_flow_job_instance
GROUP BY job_definition_id
) t2
ON t1.job_definition_id = t2.job_definition_id
AND t1.start_time = t2.max_start_time
WHERE t1.job_definition_id = d.id
ORDER BY t1.id DESC
LIMIT 1
)



        AND d.id = #{query.id}



        AND d.job_name LIKE CONCAT('%', #{query.jobName}, '%')



        AND d.create_time  >=  #{query.createTimeStart}



        AND d.create_time  <=  #{query.createTimeEnd}



        AND i.job_status = #{query.status}



        AND d.source_type = #{query.sourceType}



        AND d.sink_type = #{query.sinkType}



        AND d.source_table LIKE CONCAT('%', #{query.sourceTable}, '%')



        AND d.sink_table LIKE CONCAT('%', #{query.sinkTable}, '%')
